export const enrichmentModules: EnrichmentModuleData[] = [{"no":1,"title":"Choosing independent state variables","sourcePages":"1, 22–24","summary":["A gas at equilibrium is described macroscopically by pressure, volume, temperature and amount. These variables are not all independent once an equation of state is specified. For an ideal gas, fixing any three fixes the fourth through PV = nRT.","In a process problem, first identify what is fixed by the apparatus: a rigid vessel fixes volume, a freely moving piston often fixes pressure, a sealed vessel fixes amount, and thermal contact may fix temperature. Most mistakes arise from applying a gas law before identifying these constraints."],"formulas":["PV=nRT","n=m/M","N=nN_A"],"exam":"Write the constraint set before writing an equation. The same physical sample can obey different simplified laws in different apparatus."},{"no":2,"title":"Why gas pressure is nearly isotropic","sourcePages":"1, 41–44","summary":["Rapid random molecular motion removes any preferred horizontal direction in an equilibrium gas. Repeated wall collisions therefore produce the same average normal stress on every wall at the same height.","Gravity does not vanish; it creates a small vertical pressure gradient. Over ordinary laboratory dimensions this variation is usually negligible, but it becomes measurable in tall columns and is essential in the atmosphere."],"formulas":["P=F_\\perp/A","dP=-\\rho g\\,dh"],"exam":"Do not state that gravity has no effect on gases. State that its effect is negligible over small laboratory height differences."},{"no":3,"title":"Absolute temperature and extrapolation","sourcePages":"1–2, 16–21","summary":["Gas-law proportionalities require an absolute temperature scale. Kelvin temperature is constructed so that the ideal-gas volume or pressure extrapolates to zero at approximately −273.15 °C.","The extrapolation does not mean a real gas can reach negative volume. Real gases liquefy before the ideal straight line reaches zero, so absolute zero is a limiting temperature rather than a directly observed zero-volume state."],"formulas":["T/\\mathrm K=t/^{\\circ}\\mathrm C+273.15","V_t=V_0(1+t/273.15)"],"exam":"Never insert Celsius temperature directly into PV = nRT or a ratio such as V1/T1 = V2/T2."},{"no":4,"title":"Pressure units without ambiguity","sourcePages":"2–4, 21–23","summary":["A pressure stated as a liquid-column height is shorthand for hydrostatic pressure. The numerical conversion depends on liquid density and local gravitational acceleration, while pascal and bar are force-per-area units.","Use one pressure unit consistently within an equation. A common efficient choice is atm with R = 0.082057 L atm mol⁻¹ K⁻¹, or bar with R = 0.08314 L bar mol⁻¹ K⁻¹."],"formulas":["1\\,atm=760\\,torr=101325\\,Pa","1\\,bar=10^5\\,Pa","\\Delta P=\\rho gh"],"exam":"cm Hg and mm Hg are pressure units only after the implied mercury density is understood."},{"no":5,"title":"Barometer logic and practical corrections","sourcePages":"2","summary":["A barometer balances atmospheric pressure against the weight of a liquid column. In an ideal mercury barometer the space above the column is a vacuum, so Patm = ρHggh.","For high-precision measurements one may correct for mercury vapour pressure, temperature-dependent density, capillary depression and local g. These corrections are normally ignored in JEE calculations unless data are supplied."],"formulas":["P_{atm}=\\rho_{Hg}gh"],"exam":"The tube shape does not affect the hydrostatic head; only the vertical height difference does."},{"no":6,"title":"Open-end manometer sign rule","sourcePages":"3","summary":["Instead of memorising plus and minus cases, compare the liquid levels. The side with the lower liquid surface is under the higher pressure because that pressure pushes the liquid farther down.","If the gas-side level is lower, Pgas exceeds Patm by ρgh. If the gas-side level is higher, Pgas is smaller than Patm by ρgh. Equal levels imply equal pressures."],"formulas":["P_g=P_{atm}+\\rho gh","P_g=P_{atm}-\\rho gh"],"exam":"Draw arrows for pressure on both limbs before writing the equation; this prevents almost every sign error."},{"no":7,"title":"Inclined and multi-liquid manometers","sourcePages":"5–8","summary":["For an inclined liquid plug of length L at angle θ to the horizontal, the vertical head is L sin θ. The gas volume in a uniform tube is proportional to the trapped length, not to the plug’s vertical projection.","For several immiscible liquids, move through the connected column and add +ρgh when descending and −ρgh when ascending. Pressures at the same horizontal level in the same continuous liquid are equal."],"formulas":["h=L\\sin\\theta","P_2-P_1=\\sum_i s_i\\rho_i gh_i"],"exam":"Tube inclination changes the pressure head but does not change the length-based gas volume in a uniform tube."},{"no":8,"title":"Trapped gas and mercury-plug problems","sourcePages":"5–8","summary":["A liquid plug can isolate a gas while transmitting a hydrostatic pressure difference. When the tube is rotated, both pressure and trapped-gas length may change, so Boyle’s law must be coupled to a geometric relation.","For a uniform cross-section A, V = Aℓ and A cancels from P1Aℓ1 = P2Aℓ2. In a closed tube with two trapped gases, write a Boyle equation for each side plus a total-length constraint."],"formulas":["P_1\\ell_1=P_2\\ell_2","\\ell_L+L_{plug}+\\ell_R=L_{tube}"],"exam":"Do not assume both trapped gases have atmospheric pressure merely because the tube was initially horizontal."},{"no":9,"title":"Boyle-law graph transformations","sourcePages":"10–15","summary":["At fixed n and T, P = k/V. The ordinary P–V plot is a rectangular hyperbola, P versus 1/V is a straight line through the origin, and PV versus either P or V is horizontal.","Logarithmic transformation gives log P = −log V + log k, so the log P–log V slope is −1. Differentiation gives dP/dV = −P/V, a useful local relation for tangent questions."],"formulas":["PV=k","\\log P=-\\log V+\\log k","dP/dV=-P/V"],"exam":"Derive each graph from an explicit y(x) equation instead of relying on visual memory."},{"no":10,"title":"Charles and Gay–Lussac graph families","sourcePages":"16–21","summary":["At constant pressure, V = (nR/P)T; at constant volume, P = (nR/V)T. Both are straight lines through the origin on a kelvin scale.","On a Celsius axis the lines intercept the temperature axis at −273.15 °C. Their slopes depend on n/P for V–T and n/V for P–T, so comparing slopes reveals pressure, volume or amount ordering."],"formulas":["V/T=nR/P","P/T=nR/V"],"exam":"A steeper V–T line at the same n means lower pressure, whereas a steeper P–T line means smaller volume."},{"no":11,"title":"Standard states and molar volume","sourcePages":"21–23","summary":["The phrase STP is convention-sensitive. At 0 °C and 1 bar, the ideal molar volume is about 22.710 L mol⁻¹; at 0 °C and 1 atm it is about 22.414 L mol⁻¹.","Always read the pressure definition supplied in the question. SATP usually refers to 25 °C and 1 bar, but the numerical standard should be stated rather than assumed when precision matters."],"formulas":["V_m=RT/P","V_m(273.15\\,K,1\\,bar)=22.710\\,L\\,mol^{-1}"],"exam":"A 1.3% difference between bar-STP and atm-STP can change a close numerical option."},{"no":12,"title":"Universal gas constant and dimensions","sourcePages":"22–23","summary":["The gas constant is universal, but its numerical value changes with the chosen pressure and volume units. Dimensional consistency is often faster than memorising conversions.","In SI, R = 8.3144626 J mol⁻¹ K⁻¹ because Pa m³ = J. In caloric units R ≈ 1.987 cal mol⁻¹ K⁻¹."],"formulas":["R=8.3144626\\,J\\,mol^{-1}K^{-1}","R=0.082057\\,L\\,atm\\,mol^{-1}K^{-1}"],"exam":"Use one R value from start to finish; do not mix litres with pascals or cubic metres with atmospheres."},{"no":13,"title":"Density, molar mass and gas identification","sourcePages":"23","summary":["Combining PV = nRT with n = m/M and density d = m/V gives d = PM/RT. At fixed temperature, density is proportional to pressure and molar mass.","The relation also gives molar mass from gas density. For mixtures, replace M by mean molar mass only when the sample is compositionally uniform and behaves ideally."],"formulas":["d=PM/RT","M=dRT/P"],"exam":"Check density units carefully: many source problems intend g L⁻¹ even when a scan reads g mL⁻¹."},{"no":14,"title":"Variable amount and open-vessel heating","sourcePages":"24, 36–38, 127–129","summary":["For a rigid vessel at fixed temperature, pressure is proportional to the amount. For an open vessel held at atmospheric pressure and fixed volume, heating expels gas so n is inversely proportional to T.","The general comparison is P1V1/(n1T1) = P2V2/(n2T2). Avoid using a fixed-mass gas law when gas can enter or leave."],"formulas":["P_1V_1/(n_1T_1)=P_2V_2/(n_2T_2)","n_2/n_1=T_1/T_2\\;(P,V\\ constant)"],"exam":"A vessel may be geometrically closed yet have a valve that makes n variable after a threshold pressure is reached."},{"no":15,"title":"Connected vessels at different temperatures","sourcePages":"37, 128–130","summary":["When connected vessels reach mechanical equilibrium, they have a common final pressure, but each vessel can contain a different number of moles if maintained at a different temperature.","For rigid volumes Vi at temperatures Ti, total moles satisfy ntotal = Σ(PVi/RTi), giving P = ntotal R / Σ(Vi/Ti). This compact relation handles any number of connected bulbs."],"formulas":["P= n_{tot}R/\\sum_i(V_i/T_i)"],"exam":"Equal vessel volumes do not imply equal final moles when their temperatures differ."},{"no":16,"title":"Rigid, piston, balloon and tyre-type containers","sourcePages":"36–38","summary":["A thick rigid vessel fixes volume and can support a pressure difference. A massless frictionless piston exposed to a fixed external load keeps gas pressure nearly constant while volume changes.","A thin balloon initially expands at nearly constant pressure until elastic tension becomes important; a tyre-like container can show both volume and pressure change. The mechanical model, not the material name, determines the gas-law constraint."],"formulas":["P_{gas}=P_{ext}+W/A"],"exam":"For a piston, include atmospheric pressure and piston weight unless the problem explicitly neglects them."},{"no":17,"title":"Dalton law from molecular independence","sourcePages":"24–25","summary":["For a nonreacting ideal-gas mixture, each species contributes the pressure it would exert alone in the same volume at the same temperature. Total pressure is the sum of these partial pressures.","Because Pi = niRT/V, the partial-pressure fraction equals the mole fraction: Pi/P = ni/ntotal = xi. The relation remains useful after mixing gases initially stored at different pressures and volumes."],"formulas":["P=\\sum_iP_i","P_i=x_iP","P_i=n_iRT/V"],"exam":"Dalton’s law is about a common final volume and temperature; do not add initial vessel pressures directly."},{"no":18,"title":"Amagat law and partial volumes","sourcePages":"26","summary":["At a common temperature and pressure, the ideal mixture volume equals the sum of component partial volumes. The partial volume Vi is the volume component i would occupy alone at the mixture T and P.","Since Vi = niRT/P, Vi/Vtotal = xi. Dalton and Amagat are parallel results based on different common constraints."],"formulas":["V=\\sum_iV_i","V_i=x_iV"],"exam":"Do not confuse partial volume with the actual spatial region occupied by a species; ideal gases interpenetrate the entire container."},{"no":19,"title":"Mean molar mass and composition","sourcePages":"24–33, 134–145","summary":["For an ideal mixture, mean molar mass is the mole-fraction weighted average, M̄ = ΣxiMi. Mixture density then follows d = PM̄/RT.","Mass fraction wi and mole fraction xi are related through wi = xiMi/M̄. This relation is central in ozonised oxygen, dissociation and effusion-composition problems."],"formulas":["\\bar M=\\sum_ix_iM_i","w_i=x_iM_i/\\bar M"],"exam":"An arithmetic average of molar masses is valid only for an equimolar mixture."},{"no":20,"title":"Gas collected over water","sourcePages":"39–40, 136–140","summary":["A gas collected over water is saturated with water vapour when liquid water is present long enough at fixed temperature. The measured pressure is the sum of dry-gas pressure and water vapour pressure.","Dry-gas moles must be calculated from Pdry = Ptotal − PH2O. On changing temperature, water vapour pressure is reset by phase equilibrium only if liquid water remains available."],"formulas":["P_{total}=P_{dry}+P_{H_2O}"],"exam":"Do not scale the saturated vapour partial pressure by Boyle’s law when liquid water remains; use the new equilibrium vapour pressure."},{"no":21,"title":"Evaporation, condensation and boiling","sourcePages":"34, 39–40","summary":["Evaporation is a surface process that can occur at any temperature when sufficiently energetic molecules escape. Condensation returns vapour molecules to the liquid. In a closed vessel, dynamic equilibrium is reached when the two rates become equal.","Boiling begins when the liquid vapour pressure equals the external pressure, allowing vapour bubbles to survive within the liquid. Lower external pressure therefore lowers boiling point."],"formulas":["P_{vap}(T_b)=P_{external}"],"exam":"Equilibrium requires equal rates, not equal numbers of liquid and vapour molecules."},{"no":22,"title":"Factors controlling vapour pressure","sourcePages":"34–40","summary":["At equilibrium, vapour pressure of a pure liquid depends mainly on temperature and the identity of the liquid. Stronger intermolecular attractions lower vapour pressure and raise boiling point.","For a sufficient amount of liquid in a closed vessel, equilibrium vapour pressure is independent of liquid surface area, container volume and amount of liquid; those factors affect the rate or whether enough liquid remains, not the final saturation pressure."],"formulas":["d\\ln P/dT=\\Delta H_{vap}/(RT^2)"],"exam":"Surface area changes the time needed to reach equilibrium, not the equilibrium vapour pressure."},{"no":23,"title":"Relative humidity as a pressure ratio","sourcePages":"35, 138–140","summary":["Relative humidity compares the actual water-vapour partial pressure with the saturation vapour pressure at the same temperature. It is not directly the mass fraction of water in air.","Cooling moist air raises relative humidity because saturation vapour pressure decreases. At the dew point, RH reaches 100% and further cooling causes condensation."],"formulas":["RH=100\\,P_{H_2O}/P^*_{H_2O}(T)"],"exam":"Use partial pressure, not total atmospheric pressure, in the numerator."},{"no":24,"title":"Integrated Clausius–Clapeyron equation","sourcePages":"39–40, 141–142","summary":["If vapour behaves ideally and liquid molar volume is negligible, the Clapeyron equation integrates to relate vapour pressures at two temperatures. The usual approximation treats ΔHvap as constant over the interval.","A plot of ln P against 1/T is then nearly linear with slope −ΔHvap/R. Use kelvin and natural logarithms unless the base-10 form is written explicitly."],"formulas":["\\ln(P_2/P_1)=-\\Delta H_{vap}/R(1/T_2-1/T_1)"],"exam":"The sign is easiest checked physically: increasing T must increase Pvap."},{"no":25,"title":"Graham law and its valid comparison","sourcePages":"27–33, 143–145","summary":["For gases effusing through the same small orifice under identical temperature and pressure conditions, the initial molar rate is inversely proportional to the square root of molar mass.","The proportionality constant depends on orifice area, pressure and temperature, so Graham’s law is most reliable for comparing two gases under matched conditions rather than predicting an absolute rate from molar mass alone."],"formulas":["r_1/r_2=\\sqrt{M_2/M_1}=\\sqrt{d_2/d_1}"],"exam":"For equal quantities, time is inversely proportional to rate: t1/t2 = √(M1/M2)."},{"no":26,"title":"Finite effusion and changing composition","sourcePages":"29–33, 144–145","summary":["Graham’s law directly compares initial rates. During prolonged effusion, the lighter component is lost faster, so composition and rates continuously change.","For a well-mixed vessel in the molecular-flow limit, each component follows ni = ni0 exp(−kit), with ki proportional to 1/√Mi. This exponential form is the correct tool for finite leakage."],"formulas":["n_i(t)=n_{i0}e^{-k_it}","k_i/k_j=\\sqrt{M_j/M_i}"],"exam":"Do not apply one constant rate over a long interval unless the pressure change is negligibly small."},{"no":27,"title":"Sequential effusion enrichment","sourcePages":"32–33, 145","summary":["The initial effusate is enriched in the lighter gas by the factor √(Mheavy/Mlight) in the light-to-heavy mole ratio. Repeating the collection-and-effusion step multiplies this enrichment factor at each stage.","After s idealised stages, R_s = R_0(Mheavy/Mlight)^{s/2}. This is a conceptual model of isotope separation and is valid only for infinitesimal initial effusate samples at each stage."],"formulas":["R_s=R_0(M_H/M_L)^{s/2}"],"exam":"State whether the question asks for gas remaining in the vessel or gas collected outside; their enrichment directions are opposite."},{"no":28,"title":"Leakage, pressure decay and repair","sourcePages":"144, 149–151","summary":["At constant temperature and volume, partial pressure is proportional to moles. Molecular leakage therefore gives the same exponential law for pressure as for amount.","A calibration experiment with one gas can determine its decay constant. Constants for other gases scale as 1/√M, allowing composition after a specified leakage time to be predicted."],"formulas":["P_i(t)=P_{i0}e^{-k_it}"],"exam":"Use partial pressures for mixture leakage, not the total pressure as though all species had one decay constant."},{"no":29,"title":"Kinetic-theory assumptions and corrections","sourcePages":"41","summary":["The elementary ideal-gas model treats molecules as point particles in continuous random straight-line motion between instantaneous, perfectly elastic collisions. Intermolecular forces and molecular volume are neglected.","Random molecular motion is not Brownian motion. Brownian motion refers to visible suspended particles buffeted by much smaller molecules. The ideal assumptions become increasingly accurate at low density and high temperature."],"formulas":["PV=\\tfrac13Nm\\overline{u^2}"],"exam":"A collision can change an individual molecule’s kinetic energy, while the total kinetic energy of the colliding pair is conserved."},{"no":30,"title":"Pressure derivation from a molecular beam","sourcePages":"42–46","summary":["For a molecule with x-velocity ux colliding elastically with a wall, the momentum change is 2mux. The time between successive impacts on the same wall is 2L/|ux|, giving an average force mux²/L.","Summing over molecules and using isotropy, Σux² = (1/3)Σu², yields PV = (1/3)Nm urms². The derivation explains why pressure depends on mean square speed rather than average speed."],"formulas":["PV=\\frac13Nm u_{rms}^2","P=\\frac13\\rho u_{rms}^2"],"exam":"The relevant average is over u²; replacing it by (uav)² is generally incorrect."},{"no":31,"title":"Translational kinetic energy and equipartition","sourcePages":"43–46","summary":["Combining the kinetic gas equation with PV = nRT gives mean translational kinetic energy 3kBT/2 per molecule and 3RT/2 per mole.","This translational result is universal for ideal gases, independent of molar mass. Internal rotational and vibrational contributions affect heat capacity but do not alter the pressure relation derived from centre-of-mass translation."],"formulas":["\\langle E_{tr}\\rangle=\\tfrac32k_BT","E_{tr,m}=\\tfrac32RT"],"exam":"At the same temperature, light and heavy gases have equal average translational kinetic energy but different characteristic speeds."},{"no":32,"title":"Average, rms and most probable speeds","sourcePages":"47–50","summary":["For a Maxwellian gas, ump = √(2RT/M), uav = √(8RT/πM), and urms = √(3RT/M). Therefore urms > uav > ump.","All three scale as √T and 1/√M. The exact ratios are independent of gas identity and temperature when the Maxwell distribution applies."],"formulas":["u_{mp}=\\sqrt{2RT/M}","u_{av}=\\sqrt{8RT/(\\pi M)}","u_{rms}=\\sqrt{3RT/M}"],"exam":"Use molar mass in kg mol⁻¹ when R is in SI units."},{"no":33,"title":"Maxwell speed distribution from probability","sourcePages":"51–65","summary":["The velocity components are independent Gaussian variables. Multiplying their distributions and converting from Cartesian velocity space to a spherical shell gives the speed distribution f(u) proportional to u²exp(−Mu²/2RT).","The u² factor counts the number of velocity states in a shell, while the exponential penalises high kinetic energy. Their competition creates a peak at the most probable speed."],"formulas":["f(u)=4\\pi(M/2\\pi RT)^{3/2}u^2e^{-Mu^2/(2RT)}"],"exam":"The area under f(u) between u1 and u2 is a fraction of molecules, not a probability density value at one speed."},{"no":34,"title":"Temperature and mass effects on Maxwell curves","sourcePages":"54–58","summary":["Raising temperature shifts the peak to higher speed, lowers its height and broadens the distribution while preserving total area. Increasing molar mass at fixed temperature shifts the curve left and makes it narrower and taller.","The high-speed tail grows strongly with temperature, which explains the temperature sensitivity of escape, effusion and activated molecular processes."],"formulas":["u_{mp}\\propto\\sqrt{T/M}"],"exam":"Curves for the same number of molecules must enclose equal total area even when their peaks differ."},{"no":35,"title":"Mixture speed comparisons and energy scaling","sourcePages":"47–65","summary":["At a common temperature, speed ratios are inverse square roots of molar-mass ratios. A light gas therefore has a broader distribution and a larger rms speed.","To make two different gases have equal rms speed, their temperatures must be proportional to their molar masses. Equal speed does not imply equal kinetic energy unless molecular masses are also equal."],"formulas":["u_{rms,1}/u_{rms,2}=\\sqrt{T_1M_2/(T_2M_1)}"],"exam":"For electrons or individual particles, use particle mass and kB rather than molar mass and R."},{"no":36,"title":"Collision diameter and cross-section","sourcePages":"66–69","summary":["Two hard-sphere molecules collide when their centres approach within the sum of their radii. The collision diameter is σ = d for identical molecules and (dA + dB)/2 in common diameter notation for unlike pairs.","The effective collision cross-section is πσ². It is much larger than the geometrical cross-section of one molecular centre because either centre can lie within the collision circle."],"formulas":["\\sigma_{AB}=(d_A+d_B)/2","A_c=\\pi\\sigma_{AB}^2"],"exam":"Textbooks use σ for either diameter or cross-section in different conventions; inspect the formula before substituting."},{"no":37,"title":"Collision frequency for one molecule","sourcePages":"66–72","summary":["A moving molecule sweeps a collision cylinder of volume πσ²u dt. Multiplying by number density gives the number of target molecules encountered.","Because all molecules move, relative speed introduces a factor √2 for identical Maxwellian molecules. The single-molecule collision frequency is z1 = √2 πσ² nnumber uav."],"formulas":["z_1=\\sqrt2\\pi\\sigma^2(N/V)u_{av}"],"exam":"Distinguish collision frequency per molecule from total collisions per unit volume; the latter includes a factor 1/2 to avoid double counting pairs."},{"no":38,"title":"Mean free path","sourcePages":"70–72","summary":["Mean free path is the average distance travelled between successive collisions. It equals average speed divided by collision frequency.","For a hard-sphere ideal gas λ = kBT/(√2πσ²P). Thus λ increases with temperature, decreases with pressure and increases for smaller collision diameter."],"formulas":["\\lambda=u_{av}/z_1","\\lambda=k_BT/(\\sqrt2\\pi\\sigma^2P)"],"exam":"At fixed number density λ is nearly independent of temperature in the hard-sphere model; at fixed pressure it is proportional to T."},{"no":39,"title":"Wall-collision rate and molecular flux","sourcePages":"73–79","summary":["For an isotropic gas, the number of molecules striking unit wall area per unit time is one quarter of number density times average speed. The 1/4 factor combines the fraction moving toward the wall with the angular projection of velocity.","Molar flux to a wall is P/√(2πMRT). Multiplying by orifice area gives the ideal molecular-effusion rate into vacuum."],"formulas":["J_N=\\tfrac14(N/V)u_{av}","J_n=P/\\sqrt{2\\pi MRT}"],"exam":"The wall flux contains uav, whereas kinetic pressure contains urms²."},{"no":40,"title":"Knudsen effusion and very low vapour pressure","sourcePages":"80","summary":["In the molecular-flow regime, molecules escape through a hole whose dimensions are small compared with the mean free path. The measured mass-loss rate can therefore be related to vapour pressure through kinetic theory.","A transmission coefficient may be required for a finite-length orifice because some molecules collide with the channel wall and return. This method is useful for substances with extremely low vapour pressure."],"formulas":["dm/dt=A P\\sqrt{M/(2\\pi RT)}"],"exam":"Knudsen effusion assumes molecular flow; it is not the same as viscous bulk flow through a large opening."},{"no":41,"title":"Compressibility factor as a deviation map","sourcePages":"81–87","summary":["The compressibility factor Z = PVm/RT equals 1 for an ideal gas. Z < 1 indicates that attractions make the gas easier to compress than an ideal gas; Z > 1 indicates dominant excluded-volume or repulsive effects.","All real gases approach Z = 1 as P → 0. Many gases first show negative deviation at moderate pressure and positive deviation at high pressure, while H2 and He often show positive deviation over a broad ordinary-temperature range."],"formulas":["Z=PV_m/RT"],"exam":"A single state with Z = 1 does not make the substance an ideal gas; attractive and repulsive deviations may cancel at that state."},{"no":42,"title":"Intermolecular potential and force regions","sourcePages":"87–89","summary":["A realistic pair potential has a steep repulsive wall at short separation and an attractive well at intermediate separation. Force is the negative derivative of potential energy with respect to separation.","At large distance both potential and force approach zero. The minimum of the potential marks the equilibrium separation of an isolated pair, where attractive and repulsive forces balance."],"formulas":["F(r)=-dU/dr"],"exam":"Positive deviation in Z is associated with short-range repulsion or excluded volume, not with attractive forces."},{"no":43,"title":"van der Waals corrections","sourcePages":"88–95","summary":["Finite molecular size reduces the free volume from V to V − nb. Attractions reduce the measured wall pressure, so the pressure that would appear in an ideal relation is P + a(n/V)².","Combining both corrections gives (P + an²/V²)(V − nb) = nRT. Parameter a measures attraction strength approximately, while b reflects excluded volume."],"formulas":["(P+a n^2/V^2)(V-nb)=nRT"],"exam":"b is not simply the physical molar volume of molecules; for hard spheres it is approximately four times that volume."},{"no":44,"title":"Virial equation and low-pressure expansion","sourcePages":"95–103","summary":["Real-gas behaviour can be represented as a power series in pressure or inverse molar volume. The second virial coefficient captures leading pair-interaction effects and changes sign with temperature.","For the van der Waals equation, the low-density expansion gives B(T) = b − a/RT. Higher virial coefficients describe increasingly complex interaction and density effects."],"formulas":["Z=1+B(T)/V_m+C(T)/V_m^2+\\cdots","B_{vdW}=b-a/(RT)"],"exam":"The pressure-form and density-form virial coefficients are related but not numerically identical beyond the first correction."},{"no":45,"title":"Boyle temperature","sourcePages":"96–100","summary":["The Boyle temperature is the temperature at which the second virial coefficient vanishes, so a real gas initially follows ideal behaviour to first order in pressure.","For a van der Waals gas, TB = a/(Rb). At TB the initial slope of Z versus P is zero, but high-pressure deviations remain because excluded-volume effects become strong."],"formulas":["B(T_B)=0","T_B=a/(Rb)"],"exam":"Boyle temperature does not make a gas ideal at all pressures."},{"no":46,"title":"Critical constants of a van der Waals gas","sourcePages":"103, 112–117","summary":["At the critical point, the isotherm has a horizontal point of inflection. Therefore both first and second derivatives of pressure with respect to molar volume vanish at Tc.","Applying these conditions to the van der Waals equation yields Vc = 3b, Pc = a/(27b²), Tc = 8a/(27Rb), and Zc = 3/8. Real gases have different Zc values, showing the model’s limitations."],"formulas":["(\\partial P/\\partial V_m)_T=0","(\\partial^2P/\\partial V_m^2)_T=0","Z_c=3/8"],"exam":"At criticality liquid and vapour densities become equal; it is not merely the point where a gas first starts condensing."},{"no":47,"title":"Andrews isotherms and phase coexistence","sourcePages":"104–110","summary":["Below Tc, compression first increases pressure in the gas region, then produces condensation at nearly constant saturation pressure, and finally compresses the liquid only slightly.","At Tc the horizontal coexistence segment shrinks to a point of inflection. Above Tc no sharp liquid–gas boundary exists and compression produces a continuous supercritical fluid."],"formulas":["T<T_c:\\;gas\\to gas+liquid\\to liquid"],"exam":"Pressure alone cannot liquefy a gas when T > Tc."},{"no":48,"title":"Maxwell construction and lever rule","sourcePages":"108–113","summary":["The oscillatory van der Waals loop contains metastable and mechanically unstable portions and is not followed as an equilibrium path. Maxwell replaces it with a horizontal line whose equal areas ensure equal molar Gibbs energy of liquid and vapour.","Within the two-phase region, the lever rule converts the overall molar volume into liquid and vapour fractions using the saturated endpoint volumes."],"formulas":["\\int_{V_l}^{V_g}[P(V)-P_{sat}]dV=0","y_g=(\\bar V-V_l)/(V_g-V_l)"],"exam":"The intermediate van der Waals root is not the equilibrium molar volume of a third phase."},{"no":49,"title":"Joule–Thomson inversion and liquefaction","sourcePages":"118–119","summary":["Throttling through a valve or porous plug is approximately an isenthalpic steady-flow process. A real gas cools when μJT = (∂T/∂P)H is positive and warms when it is negative.","The inversion curve separates these regions. Hydrogen and helium at room temperature lie above their usual inversion temperatures and therefore require precooling before throttling can produce cooling."],"formulas":["\\mu_{JT}=(\\partial T/\\partial P)_H","T_{i,max}^{vdW}\\approx2a/(Rb)"],"exam":"Do not call throttling an adiabatic reversible expansion; it is highly irreversible and approximately constant enthalpy."},{"no":50,"title":"Corresponding states, atmosphere and balloon payload","sourcePages":"120–122","summary":["Reduced variables compare fluids relative to their critical constants. The reduced van der Waals equation contains no substance-specific a or b, motivating the law of corresponding states.","Hydrostatic balance combined with ideal-gas density gives exponential pressure decrease in an isothermal atmosphere. For a balloon, useful payload equals displaced-air mass minus envelope and lifting-gas mass, with all gas densities evaluated at the same ambient P and T."],"formulas":["(P_r+3/V_r^2)(3V_r-1)=8T_r","P(h)=P_0e^{-Mgh/(RT)}","m_{payload}=\\rho_{air}V-m_{gas}-m_{envelope}"],"exam":"Buoyant force depends on displaced ambient air, not on the pressure initially used to fill the balloon after it reaches ambient equilibrium."}];

